import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { fetchCatalogue } from '../server/catalogue.js';
import type { IncomingMessage, ServerResponse } from 'node:http';

export default async function handler(req: IncomingMessage, res: ServerResponse) {
  if (req.method && !['GET', 'HEAD'].includes(req.method)) {
    res.writeHead(405, { Allow: 'GET, HEAD' }); return res.end();
  }
  try {
    // Generated by the SSR build and explicitly included in the function bundle.
    const renderer = path.join(process.cwd(), 'server-dist/entry-server.js');
    const { pathToFileURL } = await import('node:url');
    const { render } = await import(pathToFileURL(renderer).href);
    const pathname = new URL(req.url || '/', 'https://pokesmith.com').pathname;
    const catalogue = pathname === '/' || /^\/hacks?(\/|$)/.test(pathname) ? await fetchCatalogue() : null;
    const result = render(req.url || '/', catalogue);
    if (result.location) {
      res.writeHead(result.status, { Location: result.location, 'Cache-Control': 'public, max-age=300' });
      return res.end();
    }
    const template = await readFile(path.join(process.cwd(), 'dist/index.html'), 'utf8');
    const html = template.replace(/<title>[\s\S]*?<\/title>/, '').replace(/<meta\s+name="description"[\s\S]*?\/>/, '')
      .replace('</head>', `${result.head}</head>`)
      .replace('<div id="root"></div>', `<div id="root">${result.html}</div><script id="pokesmith-data" type="application/json">${result.data}</script>`);
    res.writeHead(result.status, {
      'Content-Type': 'text/html; charset=utf-8',
      'Cache-Control': result.status === 200 && !/^\/(admin|login)/.test(req.url || '') ? 'public, max-age=0, s-maxage=300' : 'no-store',
    });
    res.end(req.method === 'HEAD' ? undefined : html);
  } catch (error) {
    console.error('Page rendering failed:', error instanceof Error ? error.message : 'unknown error');
    res.writeHead(503, { 'Content-Type': 'text/html; charset=utf-8', 'Retry-After': '300', 'Cache-Control': 'no-store' });
    res.end('<!doctype html><html lang="en"><title>Temporarily unavailable | PokéSmith</title><h1>Temporarily unavailable</h1><p>Please try again shortly.</p></html>');
  }
}
